#!/usr/bin/env node
/* Differential harness: reference executable vs the Node port. */
import { execFileSync, spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test4_executable';
const JS = '/output/test4.mjs';

function run(cmd, args, argv, cwd, env) {
  const r = spawnSync(cmd, [...args, ...argv], {
    cwd, encoding: 'buffer', env: { ...process.env, ...env },
  });
  return {
    code: r.status,
    out: r.stdout.toString('utf8'),
    err: r.stderr.toString('utf8'),
  };
}

// Normalize the two legitimately-variable pieces of stderr:
//   - the PYI tag carries the pid
//   - argparse's prog name comes from argv[0]/argv[1]
function norm(s) {
  return s
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]')
    .replace(/test4_executable|test4\.mjs/g, 'PROG');
}

const CASES = JSON.parse(process.argv[2]);
const cwd = process.argv[3] || '/workspace/dataset';

let pass = 0;
const fails = [];
for (const argv of CASES) {
  const a = run(EXE, [], argv, cwd);
  const b = run('node', [JS], argv, cwd);
  const problems = [];
  if (a.code !== b.code) problems.push(`exit ${a.code} vs ${b.code}`);
  if (norm(a.out) !== norm(b.out)) problems.push(`stdout ${JSON.stringify(norm(a.out))} vs ${JSON.stringify(norm(b.out))}`);
  if (norm(a.err) !== norm(b.err)) {
    problems.push(`stderr\n  py=${JSON.stringify(norm(a.err))}\n  js=${JSON.stringify(norm(b.err))}`);
  }
  if (problems.length === 0) pass += 1;
  else fails.push({ argv, problems });
}

console.log(`cwd=${cwd}  pass ${pass}/${CASES.length}`);
for (const f of fails) {
  console.log(`FAIL ${JSON.stringify(f.argv)}`);
  for (const p of f.problems) console.log(`   ${p}`);
}
process.exitCode = fails.length ? 1 : 0;
